package cn.sixnine.filmlog;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;

public final class WidgetHalfFrameInstrumentation extends Instrumentation {
    interface Action{void run()throws Exception;}int checks;Activity host;Context c;LogStore logs;RollWizard wizard;Bundle draft;String saved;Dialog sheet;int offset=0;
    void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    void main(Action action)throws Exception{Throwable[] failure={null};runOnMainSync(()->{try{action.run();}catch(Throwable t){failure[0]=t;}});waitForIdleSync();if(failure[0]!=null)throw new RuntimeException(failure[0]);}
    Object field(Object obj,String name)throws Exception{java.lang.reflect.Field f=obj.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
    Object call(Object obj,String name,Class<?>[] types,Object...args)throws Exception{java.lang.reflect.Method m=obj.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(obj,args);}
    List<View> all(View v){List<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(all(((ViewGroup)v).getChildAt(i)));return out;}
    Button button(View root,String label){for(View v:all(root))if(v instanceof Button&&label.contentEquals(((Button)v).getText()))return(Button)v;throw new AssertionError(label);}
    EditText input(View root){for(View v:all(root))if(v instanceof EditText)return(EditText)v;throw new AssertionError("input");}
    void open(Bundle state){draft=state;wizard=new RollWizard(host,logs,state,()->{},id->saved=id);wizard.show();}
    void snap(View view,String name,int width)throws Exception{int w=LibraryUi.dp(view.getContext(),width);view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));view.layout(0,0,w,view.getMeasuredHeight());Bitmap b=Bitmap.createBitmap(w,Math.max(1,view.getHeight()),Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));File out=new File(getTargetContext().getFilesDir(),name+".png");try(FileOutputStream f=new FileOutputStream(out)){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle out=new Bundle();String prior=Workspace.current(getTargetContext());boolean ok=false;try{
        check(getTargetContext().getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated app only");Workspace.activate(getTargetContext(),UUID.randomUUID().toString());c=Workspace.context(getTargetContext());logs=new LogStore(c);CatalogStore catalog=new CatalogStore(logs);host=startActivitySync(new Intent(getTargetContext(),ReferenceSaveInstrumentation.Host.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->host.setTheme(R.style.AppTheme));
        main(()->{open(new Bundle());wizard.useStock("original:kodak_portra_400");View root=(View)field(wizard,"root");CheckBox half=null;for(View v:all(root))if(v instanceof CheckBox)half=(CheckBox)v;check(half!=null&&!half.isChecked(),"default full-frame");half.performClick();check(draft.getBoolean("halfFrame"),"half toggle");snap(root,"half-wizard",375);half.performClick();half.performClick();check(call(wizard,"capacity",new Class<?>[]{ }).equals(72),"toggle never compounds");draft.putString("capacity","24");check(call(wizard,"capacity",new Class<?>[]{ }).equals(48),"24 doubles48");draft.putString("capacity","36");draft.putString("camera","Nikon FE2");((Button)field(wizard,"next")).performClick();((Button)field(wizard,"next")).performClick();check(logs.roll(saved).capacity==72&&catalog.detail(saved).halfFrame,"manual72 half persisted");Bundle replay=new Bundle(draft);open(replay);((Button)field(wizard,"next")).performClick();check(logs.rolls().size()==1&&logs.roll(saved).capacity==72,"manual retry idempotent");});
        String halfRoll=saved;for(int i=0;i<73;i++)logs.insert(halfRoll,100000+i*1000,0,480,"denied","8","1/125","","synthetic only","","");check(logs.nextFrame(halfRoll)==74&&logs.roll(halfRoll).count==73,"overcapacity still recordable");
        CatalogStore.Batch batch=new CatalogStore.Batch();batch.stock="Fixture 400";batch.format="35 mm";batch.iso=400;batch.capacity=36;batch.quantity=2;batch.threshold=0;batch.location=batch.temperature=batch.expiry=batch.purchaseDate=batch.price=batch.currency=batch.notes="";catalog.saveBatch(batch,0);
        main(()->{open(new Bundle());call(wizard,"selectBatch",new Class<?>[]{CatalogStore.Batch.class},catalog.batch(batch.id));draft.putBoolean("halfFrame",true);((Button)field(wizard,"next")).performClick();((Button)field(wizard,"next")).performClick();check(logs.roll(saved).capacity==72&&catalog.batch(batch.id).quantity==1,"inventory doubles capacity, consumes1");open(new Bundle(draft));((Button)field(wizard,"next")).performClick();check(catalog.batch(batch.id).quantity==1&&logs.rolls().size()==2,"inventory retry no second deduction");open(new Bundle());draft.putBoolean("halfFrame",true);call(wizard,"changeFormat",new Class<?>[]{String.class},"120");check(!draft.getBoolean("halfFrame"),"non135 clears half");((Dialog)field(wizard,"dialog")).dismiss();});
        String full=catalog.manual(UUID.randomUUID().toString(),"Full72","Synthetic","",400,72,"35 mm","","");check(!catalog.detail(full).halfFrame,"72 not inferred");
        for(int i=0;i<15;i++)logs.insert(full,200000+i*1000,0,480,"denied","","","","","","");
        main(()->{for(int width:new int[]{320,375,414})for(String id:new String[]{halfRoll,full}){ContactSheet grid=ContactSheet.film(c,logs,id,logs.shots(id),new HashMap<>(),s->{});int w=LibraryUi.dp(c,width-32);grid.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),0);grid.layout(0,0,w,grid.getMeasuredHeight());boolean half=id.equals(halfRoll);check((Integer)field(grid,"columns")== (half?14:7),"columns exact "+width);check(Math.abs((Float)field(grid,"filmAspect")-(half?.75f:1.5f))<.001,"portrait ratio");check(grid.getAccessibilityNodeProvider().createAccessibilityNodeInfo(-1).getCollectionInfo().getColumnCount()==(half?14:7),"accessible columns");if(half){host.setContentView(grid);snap(grid,"half-preview-"+width,width-32);} }});
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();FilmBackup.write(c,logs,bytes);try(FilmBackup.Prepared b=FilmBackup.inspect(c,new ByteArrayInputStream(bytes.toByteArray()))){check(b.manifest.getInt("schema")==25,"schema24");FilmBackup.restore(c,logs,b);int halves=0;for(LogStore.Roll roll:logs.rolls())if(catalog.detail(roll.id).halfFrame)halves++;check(halves==4,"backup restores flags");JSONObject d=b.manifest.getJSONArray("roll_details").getJSONObject(0);for(Object invalid:new Object[]{2,.5,"1",true}){d.put("half_frame",invalid);try{FilmBackup.validate(b);throw new AssertionError("bad flag accepted");}catch(IOException expected){checks++;}}d.put("half_frame",0);b.manifest.put("schema",23);FilmBackup.normalizeCatalog(b.manifest);for(int i=0;i<b.manifest.getJSONArray("roll_details").length();i++)check(b.manifest.getJSONArray("roll_details").getJSONObject(i).getInt("half_frame")==0,"legacy backup defaults full");}
        main(()->{sheet=OffsetEditor.show(host,-10,n->offset=n);View root=sheet.getWindow().getDecorView();button(root,"+10").performClick();snap(root,"offset-sheet",375);button(root,"取消").performClick();check(offset==0,"cancel preserves setting");sheet=OffsetEditor.show(host,0,n->offset=n);root=sheet.getWindow().getDecorView();EditText number=input(root);number.setText("3601");check(!button(root,"保存偏移").isEnabled(),"invalid disabled");number.setText("");check(!button(root,"保存偏移").isEnabled(),"empty disabled");button(root,"-10").performClick();button(root,"保存偏移").performClick();check(offset==-10,"signed value saved");});
        // Apply the actual RemoteViews in both palettes; host size bounds are independent of its launcher.
        Workspace.root(c).getSharedPreferences(ExposureWidget.PREFS,0).edit().putString("987.workspace",Workspace.current(c)).putString("987.roll",halfRoll).commit();
        main(()->{for(boolean dark:new boolean[]{false,true})for(float scale:new float[]{1f,1.3f})for(int width:new int[]{220,320,375,414}){Configuration config=new Configuration(c.getResources().getConfiguration());config.uiMode=(config.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);config.fontScale=scale;Context theme=c.createConfigurationContext(config);check(theme.getColor(R.color.ui_film_band)==(dark?0xff252a26:0xff552e21),"band palette");for(int layout:new int[]{R.layout.exposure_widget,R.layout.exposure_widget_narrow}){View view=new RemoteViews(theme.getPackageName(),layout).apply(theme,null);((TextView)view.findViewById(R.id.widget_title)).setText("Kodak Ultramax 400");((TextView)view.findViewById(R.id.widget_detail)).setText("Olympus 35 DC\n35 mm 半格 · ISO 400");((TextView)view.findViewById(R.id.widget_action)).setText("记录第74张");view.measure(View.MeasureSpec.makeMeasureSpec(LibraryUi.dp(theme,width),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(LibraryUi.dp(theme,layout==R.layout.exposure_widget_narrow?480:260),View.MeasureSpec.EXACTLY));view.layout(0,0,view.getMeasuredWidth(),view.getMeasuredHeight());check(view.getHeight()<=LibraryUi.dp(theme,layout==R.layout.exposure_widget_narrow?480:260),"widget fits offered height "+width+"/"+scale);Rect bound=new Rect();view.findViewById(R.id.widget_meter).getDrawingRect(bound);((ViewGroup)view).offsetDescendantRectToMyCoords(view.findViewById(R.id.widget_meter),bound);check(bound.bottom<=view.getHeight(),"actions not clipped");}
            View actual=ExposureWidget.views(theme,987).apply(theme,null);host.setContentView(actual);if(scale==1&&width==320){snap(actual,"widget-"+(dark?"dark":"light"),width);for(int id:new int[]{R.id.widget_cover,R.id.widget_body}){View part=actual.findViewById(id);Rect b=new Rect();part.getDrawingRect(b);((ViewGroup)actual).offsetDescendantRectToMyCoords(part,b);check(b.left>=LibraryUi.dp(theme,id==R.id.widget_cover&&actual.findViewById(R.id.widget_logo_small)==null?0:8),"confirmed B cover is flush left; other content keeps inset");if(id==R.id.widget_cover){ImageView iv=(ImageView)part;RectF pixels=new RectF(iv.getDrawable().getBounds());iv.getImageMatrix().mapRect(pixels);check(pixels.left>=-.5f&&pixels.right<=iv.getWidth()+.5f,"cover fits its view: "+pixels+" width="+iv.getWidth());}}}
            View choice=WidgetCard.choice(theme,logs,logs.roll(halfRoll),true,()->{});if(scale==1&&width==320)snap(choice,"chooser-"+(dark?"dark":"light"),width);
        }});
        main(()->{sheet=OffsetEditor.show(host,10,n->offset=n);});
        SystemClock.sleep(300);Bitmap screen=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(getTargetContext().getFilesDir(),"offset-native.png"))){screen.compress(Bitmap.CompressFormat.PNG,100,f);}screen.recycle();
        main(()->{View root=sheet.getWindow().getDecorView();EditText number=input(root);check(number.getWidth()>LibraryUi.dp(host,90)&&number.getText().toString().equals("10"),"native offset input visible width");sheet.dismiss();});
        int before=logs.rolls().size();logs.getWritableDatabase().execSQL("ALTER TABLE roll_details DROP COLUMN half_frame");logs.getWritableDatabase().setVersion(22);logs.close();logs=new LogStore(c);check(logs.getReadableDatabase().getVersion()==24&&logs.rolls().size()==before,"DB22 upgrade retains records");check(!new CatalogStore(logs).detail(halfRoll).halfFrame,"legacy DB no guessed half");
        out.putString("stream","PASS "+checks+" assertions: half-frame manual/inventory/idempotency/73 exposures, exact14 portrait vs7 landscape, backup24 and DB22 migration, offset cancel/validation/save, themed RemoteViews/chooser at220/320/375/414 and1.0/1.3 fonts.\n");ok=true;
    }catch(Throwable t){out.putString("stream",android.util.Log.getStackTraceString(t));}finally{try{if(sheet!=null)main(()->sheet.dismiss());if(host!=null)main(()->host.finish());if(logs!=null)logs.close();Workspace.activate(getTargetContext(),prior);}catch(Exception ignored){}}finish(ok?-1:0,out);}
}
